AFTER='39809d546fbadc761c3beb30c77b76e5b6560de38dbad8ac575e512b7bdda6e2'
DATA=''
def check(ok,why):
 if not ok:raise RuntimeError(why)
def sha(data):return hashlib.sha256(data).hexdigest()
def run(args):return subprocess.check_output(args,stderr=subprocess.DEVNULL,timeout=30).decode().strip()
def target():
 check(os.geteuid()==0 and run(['hostname'])=='srv1011043','ROOT_OR_HOST_MISMATCH')
 fmt='{{json .State.Running}}|{{json (index .Config.Labels "com.docker.compose.project")}}|{{json .Mounts}}|{{json .NetworkSettings.Ports}}'
 w=[json.loads(s) for s in run(['docker','inspect','--format',fmt,'erp-staging-dolibarr-1']).split('|')]
 d=[json.loads(s) for s in run(['docker','inspect','--format','{{json .State.Running}}|{{json (index .Config.Labels "com.docker.compose.project")}}|{{json .NetworkSettings.Ports}}','erp-staging-mariadb-1']).split('|')]
 check(w[0] is True and d[0] is True and w[1]=='erp-staging' and d[1]=='erp-staging','STAGING_IDENTITY_MISMATCH')
 mounts=[x for x in w[2] if x['Destination']=='/var/www/html/custom']
 check(len(mounts)==1 and mounts[0]['Type']=='volume' and mounts[0]['Name']=='erp-staging_erp-staging_custom' and mounts[0]['Source']==str(ROOT) and mounts[0]['RW'],'STAGING_MOUNT_MISMATCH')
 check(w[3].get('80/tcp')==[{'HostIp':'127.0.0.1','HostPort':'18088'}] and not d[2].get('3306/tcp'),'STAGING_PORT_MISMATCH')
 check(ROOT.is_dir() and not ROOT.is_symlink() and ROOT.resolve()==ROOT,'ROOT_PATH_MISMATCH')
def read_file(root,name):
 p=root/name
 check(not Path(name).is_absolute() and '..' not in Path(name).parts,'UNSAFE_NAME')
 q=p.parent
 while q!=root:
  check(q.is_dir() and not q.is_symlink(),'SYMLINK_PARENT');q=q.parent
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW)
 with os.fdopen(fd,'rb') as f:
  a=os.fstat(f.fileno());check(stat.S_ISREG(a.st_mode) and a.st_nlink==1 and a.st_size<5000000,'UNSAFE_FILE')
  data=f.read();b=os.fstat(f.fileno());check((a.st_dev,a.st_ino,a.st_size,a.st_mtime_ns)==(b.st_dev,b.st_ino,b.st_size,b.st_mtime_ns),'CHANGING_FILE')
 return data,a
def compare(expected):
 for name,digest in expected.items():
  data,s=read_file(ROOT,name)
  check(s.st_uid in (0,33) and s.st_gid in (0,33) and stat.S_IMODE(s.st_mode)==0o644,'FILE_OWNER_MODE_DRIFT:'+name)
  check(sha(data)==digest,'FILE_DRIFT:'+name)
def atomic(data,meta,expected):
 p=ROOT/NAME;current,s=read_file(ROOT,NAME);check(sha(current)==expected,'CONCURRENT_DRIFT')
 fd,temp=tempfile.mkstemp(prefix='.m099-csrf-',dir=str(p.parent))
 try:
  with os.fdopen(fd,'wb') as f:
   f.write(data);f.flush();os.fsync(f.fileno());os.fchown(f.fileno(),meta['uid'],meta['gid']);os.fchmod(f.fileno(),meta['mode'])
  latest,st=read_file(ROOT,NAME);check(sha(latest)==expected and (st.st_ino,st.st_mtime_ns)==(s.st_ino,s.st_mtime_ns),'CONCURRENT_DRIFT')
  os.replace(temp,p)
 finally:
  if os.path.exists(temp):os.unlink(temp)
def private_write(name,data):
 fd=os.open(STATE/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
def state_guard():
 s=STATE.lstat();check(stat.S_ISDIR(s.st_mode) and s.st_uid==0 and s.st_gid==0 and stat.S_IMODE(s.st_mode)==0o700 and STATE.resolve()==STATE,'STATE_DRIFT')
def rollback():
 old,s=read_file(STATE,'before.js');meta_bytes,ms=read_file(STATE,'metadata.json')
 check(s.st_uid==0 and ms.st_uid==0 and stat.S_IMODE(s.st_mode)==0o600 and stat.S_IMODE(ms.st_mode)==0o600,'BACKUP_METADATA_DRIFT')
 check(sha(old)==EXPECTED[NAME],'BACKUP_HASH_MISMATCH');meta=json.loads(meta_bytes)
 check(meta['uid'] in (0,33) and meta['gid'] in (0,33) and meta['mode']==0o644,'BACKUP_OWNER_DRIFT')
 atomic(old,meta,AFTER);compare(EXPECTED)
