 updated=dict(EXPECTED);updated[NAME]=AFTER
 if action=='preflight':compare(EXPECTED);print('M099_CSRF_STAGING_PREFLIGHT=PASS');return
 if action=='verify':compare(updated);print('M099_CSRF_STAGING_VERIFY=PASS');return
